import {FunctionalComponent, Fragment } from 'preact';
import { useSelector } from 'react-redux';
import { useState } from 'preact/hooks';
import { selectTriviaState } from '../../slice';

import ShareIcon from '../../assets/share.svg';
import FbIcon from '../../assets/fb.svg';
import TwitterIcon from '../../assets/twitter.svg';

import FileCopyIcon from '@material-ui/icons/FileCopy';

import styles from './styles.module.scss';

const sharingUrls = {
  fb: 'https://www.facebook.com/sharer/sharer.php?u=',
  twitter: 'https://twitter.com/intent/tweet?url=',
};

const socialMediaButtons: {
  onClickArg: string;
  imgClass: string;
  imgSrc: string;
}[] = [
  {
    onClickArg: 'fb',
    imgClass: styles.fbIcon,
    imgSrc: FbIcon,
  },
  {
    onClickArg: 'twitter',
    imgClass: styles.twitterIcon,
    imgSrc: TwitterIcon,
  },
];

const ShareButton: FunctionalComponent = () => {
  const { trivia } = useSelector(selectTriviaState);

  const [isSharing, setIsSharing] = useState(false);
  const [isCopied, setCopied] = useState(false);

  const handleCopy = (): void => {
    if (navigator.clipboard) {
      navigator.clipboard.writeText(
        `I’ve found an interesting fact by using OceanHero.com: ${trivia.fact} Read more: ${trivia.readMoreLink}`
      );
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const shareTo = (mediaType: string): void => {
    if (mediaType === 'twitter') {
      window.open(
        `${sharingUrls[mediaType]}${encodeURIComponent(
          trivia.readMoreLink
        )}&text=I’ve found an interesting fact by using OceanHero.com: ${
          trivia.fact
        }`,
        'Share dialog',
        'width=550,height=450'
      );
    }
    if (mediaType === 'fb') {
      window.open(
        `${sharingUrls[mediaType]}${encodeURIComponent(
          trivia.readMoreLink
        )}&quote=I’ve found an interesting fact by using OceanHero.com: ${
          trivia.fact
        }`,
        'Share dialog',
        'width=550,height=450'
      );
    }
  };

  return (
    <Fragment>
      {isSharing ? (
        <div className={styles.socialButtons}>
          {socialMediaButtons.map((btn) => (
            <button
              type="button"
              key={btn.onClickArg}
              className={styles.socialMediaBtn}
              onClick={(): void => shareTo(btn.onClickArg)}
            >
              <img className={btn.imgClass} src={btn.imgSrc} alt="" />
            </button>
          ))}
          <button className={styles.copy} onClick={handleCopy}>
            {isCopied ? (
              'Copied'
            ) : (
              <Fragment>
                <FileCopyIcon /> Copy
              </Fragment>
            )}
          </button>
        </div>
      ) : (
        <button
          type="button"
          className={styles.shareBtn}
          onClick={(): void => setIsSharing(true)}
        >
          <img className={styles.shareImg} src={ShareIcon} alt="" />
          Share this fact
        </button>
      )}
    </Fragment>
  );
};

export default ShareButton;
