import { FunctionalComponent} from 'preact';
import Popover from '../../../../shared/Popover';

import styles from './styles.module.scss';

interface Props {
  onClose: () => void;
  hideAllShells: () => void;
  hideCurrentShell: () => void;
}

const ShellSettingPopover: FunctionalComponent<Props> = ({
  onClose,
  hideAllShells,
  hideCurrentShell,
}: Props) => (
  <Popover className={styles.shellsPopover} onClose={onClose}>
    <button onClick={hideCurrentShell}>Hide this trivia question</button>
    <button onClick={hideAllShells}>Hide trivia questions in the future</button>
  </Popover>
);

export default ShellSettingPopover;
