import { FunctionalComponent } from 'preact';
import { useEffect, useRef, useState } from 'preact/hooks';
import { useDispatch, useSelector } from 'react-redux';

import MoreButton from '../../../../../shared/MoreButton';
import { selectNtpVisitCounter } from '../../../user/slice';
import { disabledTrivia, setDialogMode, updatedVisibility } from '../../slice';
import { shellType, position } from '../../slice/utils';
import { DialogTypes } from '../../slice/types';

import ShellSettingPopover from '../ShellSettingPopover';

import styles from './styles.module.scss';

const Shell: FunctionalComponent = () => {
  const dispatch = useDispatch();
  const ntpVisitCount = useSelector(selectNtpVisitCounter);
  const [showPopover, setShowPopover] = useState(false);
  const [state, setState] = useState({
    hide: false,
    shell: shellType,
    position,
  });

  const idRef = useRef();

  const hideShell = (): void => {
    setState({ ...state, hide: true });
  };

  const hideAllShells = (): void => {
    setState({ ...state, hide: true });
    dispatch(disabledTrivia());
  };

  useEffect(() => {
    dispatch(
      updatedVisibility({
        tabs: ntpVisitCount,
        lastSeen: new Date().setHours(0, 0, 0, 0),
      })
    );

    idRef.current = setTimeout(() => {
      setState({ ...state, hide: true });
    }, 10000);

    return (): void => {
      clearTimeout(idRef.current as number);
    };
  }, []);

  const handleShellClick = (): void => {
    clearTimeout(idRef.current as number);
    setState({ ...state, hide: true });
    dispatch(setDialogMode(DialogTypes.Trivia));
  };

  return (
    <div
      className={`${styles.container} ${state.hide ? styles.hidden : ''}`}
      style={{
        top: `${state.position[0]}%`,
        left: `${state.position[1]}%`,
      }}
    >
      <button className={`${styles.shellWrapper}`} onClick={handleShellClick}>
        <img src={state.shell} className={styles.shell} alt="trivia question" />
      </button>

      <MoreButton
        className={styles.shellMoreBtn}
        onClick={(): void => setShowPopover(true)}
      />
      {showPopover && !state.hide && (
        <ShellSettingPopover
          onClose={(): void => setShowPopover(false)}
          hideCurrentShell={hideShell}
          hideAllShells={hideAllShells}
        />
      )}
    </div>
  );
};

export default Shell;
