import { FunctionalComponent, Fragment } from 'preact';
import { useEffect, useState } from 'preact/hooks';
import { useDispatch, useSelector } from 'react-redux';
import cn from 'classnames';
import {
  clearedTrivia,
  disabledTrivia,
  selectTriviaState,
  answeredQuestion,
  setCurrentTrivia,
} from '../../slice';
import { Trivia } from '../../slice/types';
import trivias from '../../slice/trivias.json';

import StateIndicator from '../../../../shared/StateIndicator';

import Close from '@material-ui/icons/Close';
import HeadingMask from './../../assets/heading.svg';
import SeaweedImg from '../../assets/seaweed.svg';
import RedShell from './../../assets/red_shell.svg';
import styles from './styles.module.scss';

const TriviaDialog: FunctionalComponent = () => {
  const dispatch = useDispatch();
  const { trivia, answers } = useSelector(selectTriviaState);
  const [selectedAnswer, setSelectedAnswer] = useState(null);

  const selectRandomTrivia = (): Trivia => {
    const filteredTrivias = trivias.filter(
      (trivia) => !answers.includes(trivia.id)
    );

    return filteredTrivias[Math.floor(Math.random() * filteredTrivias.length)];
  };

  useEffect(() => {
    dispatch(setCurrentTrivia(selectRandomTrivia()));
  }, []);

  const handleAnswerClick = (id: number): void | (() => void) => {
    setSelectedAnswer(id);
  };

  useEffect(() => {
    if (!selectedAnswer) return null;

    const timer = setTimeout(
      () => {
        dispatch(answeredQuestion(selectedAnswer));
      },
      selectedAnswer === trivia.answers.correctId ? 0 : 2000
    );

    return (): void => {
      if (timer) clearTimeout(timer);
    };
  }, [selectedAnswer]);

  const disableShellTrivia = (): void => {
    dispatch(disabledTrivia());
  };

  const hideTrivia = (): void => {
    dispatch(clearedTrivia());
  };

  return (
    <div className={styles.triviaContainer}>
      <button className={styles.close} onClick={hideTrivia}>
        <Close />
      </button>
      <div className={styles.triviaHeaderImg}>
        <img className={styles.headingMask} src={HeadingMask} alt="" />
        <img className={styles.shell} src={RedShell} alt="" />
      </div>
      <div className={styles.questionWrapper}>
        <div className={styles.question}>{trivia?.question}</div>
        <div className={styles.answers}>
          {trivia?.answers.variants.map((answer) => (
            <button
              type="button"
              className={cn(styles.answer, {
                [styles.wrong]:
                  selectedAnswer === answer.id &&
                  selectedAnswer !== trivia.answers.correctId,
                [styles.correct]:
                  selectedAnswer &&
                  answer.id === trivia.answers.correctId &&
                  (selectedAnswer === trivia.answers.correctId ||
                    selectedAnswer !== trivia.answers.correctId),
              })}
              key={answer.id}
              onClick={(): void | (() => void) => handleAnswerClick(answer.id)}
            >
              {answer.value}
            </button>
          ))}
        </div>
        {selectedAnswer ? (
          <StateIndicator type="loading" className={styles.answerIndicator} />
        ) : (
          <Fragment>
            <button className={styles.doNotShow} onClick={disableShellTrivia}>
              Don&apos;t show me trivia in the future
            </button>
            <a
              href="https://docs.google.com/forms/d/e/1FAIpQLScNbC-1x5GqYU4MKa6-GeHvOvbVTkKM_1CzIGUq1pVWxwXHTQ/viewform?usp=sf_link"
              target="_blank"
              rel="noreferrer"
              className={styles.feedback}
            >
              Provide feedback
            </a>
          </Fragment>
        )}
      </div>
      <img className={styles.seaweedImg} src={SeaweedImg} alt="Seaweed" />
    </div>
  );
};

export default TriviaDialog;
